import re
with open('/app/resources/treasury_bulletin_1969_10.txt', 'r') as f:
    content = f.read()

# Look for the table FD-1 pattern - look for lines with year-month and numbers
# Pattern: | YEAR-MONTH | Total | Public debt | Agency securities |
lines = content.split('\n')
for i, line in enumerate(lines):
    # Look for January entries
    if '-January' in line and '|' in line:
        parts = line.split('|')
        if len(parts) > 4:
            try:
                # Check if the second part looks like a year (e.g., '1969-January')
                year_month = parts[1].strip()
                if 'January' in year_month and year_month:
                    # Try to find the total column (should be a large number like 374443)
                    for j, part in enumerate(parts):
                        part = part.strip().replace(',', '')
                        if part.isdigit() and len(part) >= 5 and int(part) > 100000:
                            print(f'Line {i}: {year_month} - Total = {part}')
                            break
            except:
                pass"

